impl crate::Transform for super::SideWall {
    fn transform(&self, ctx: &mut dyn crate::Context) -> Self {
        let node = crate::ask(ctx.chart(), super::Context::side_wall, self);
        node.unwrap_or_else(|| self.transform_children(ctx))
    }

    fn transform_children(&self, ctx: &mut dyn crate::Context) -> Self {
        let mut rebase = crate::Rebase::new(&self.unknown);
        let child_1 = crate::transform_child(&self.thickness, ctx, &mut rebase);
        let child_2 = crate::transform_child(&self.shape_properties, ctx, &mut rebase);
        let child_3 = crate::transform_child(&self.picture_options, ctx, &mut rebase);
        let child_4 = crate::transform_child(&self.chart_extensibility, ctx, &mut rebase);
        Self {
            chart_extensibility: child_4,
            picture_options: child_3,
            shape_properties: child_2,
            thickness: child_1,
            unknown: crate::transform_unknown(&self.unknown, ctx, &rebase),
        }
    }
}

